export function getCompany(id: string): Company | undefined {
  return COMPANIES.find((c) => c.id === id);
}

/** Resolve a company id to its display name, for table cells. */
export function companyName(id?: string): string | undefined {
  if (!id) return undefined;
  return COMPANIES.find((c) => c.id === id)?.name;
}

/** Every registration country present, sorted, for the directory filter. */
export const COMPANY_COUNTRIES: string[] = Array.from(
  new Set(COMPANIES.map((c) => c.country).filter(Boolean) as string[]),
).sort((a, b) => a.localeCompare(b));
